targets.query:
from(bucket: "tommybot")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "vecserve" and r._field == "connections")

from(bucket: "ops")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "github_tasks_mirror" and (r._field == "written" or r._field == "deleted" or r._field == "skipped"))
